query:
-- Check the organization_users table to find the organization
SELECT * FROM organization_users WHERE userId = 9870148 LIMIT 1;

-- Get organization info
SELECT * FROM organizations WHERE id IN (
  SELECT organizationId FROM organization_users WHERE userId = 9870148
) LIMIT 1;

-- Update credits
UPDATE organizations 
SET credits = credits + 50000 
WHERE id IN (
  SELECT organizationId FROM organization_users WHERE userId = 9870148
);

-- Verify
SELECT id, name, credits FROM organizations WHERE id IN (
  SELECT organizationId FROM organization_users WHERE userId = 9870148
);

